/// <summary>
/// Extension of <c>CustVendPaym</c> class
/// </summary>
[ExtensionOf(classstr(CustVendPaym))]
public final class METCustVendPaym_Extension
{
}

Method.Source:
    /// <summary>
    /// Check payment statuses introduced for METPAY payment plus
    /// </summary>
    /// <param name = "_module">Cust or Vend</param>
    /// <param name = "_paymMode">Payment mode</param>
    /// <param name = "_actualStatus">Payment status</param>
    /// <returns>true if status is valid, otherwise false</returns>
    public static boolean metCheckPaymStatus(ModuleCustVend _module, PaymMode _paymMode, CustVendPaymStatus _actualStatus)
    {
        
        boolean                 ok = true;
        CustVendPaymStatus      neededPaymStatus;
        CustVendPaymModeTable   custVendPaymModeTable;

        custVendPaymModeTable = CustVendPaymModeTable::findModule(_module, _paymMode);

        if (!custVendPaymModeTable || _actualStatus == CustVendPaymStatus::Rejected)
        {
            return false;
        }

        neededPaymStatus = custVendPaymModeTable.PaymStatus;

        switch (neededPaymStatus)
        {
            case CustVendPaymStatus::Confirmed:
                if (_actualStatus == CustVendPaymStatus::METDueDate ||
                    _actualStatus == CustVendPaymStatus::METDueDateSent ||
                    _actualStatus == CustVendPaymStatus::METResend ||
                    _actualStatus == CustVendPaymStatus::METResendSent ||
                    _actualStatus == CustVendPaymStatus::METWithdraw ||
                    _actualStatus == CustVendPaymStatus::METWithdrawSent ||
                    _actualStatus == CustVendPaymStatus::METWithdrawn)
                {
                    ok = false;
                }
                break;
        }
        return ok;

    }
